'use strict';
const api=location.pathname.startsWith('/online/')?'./api/index.php':'../api/index.php';
const steps=[['BOOKED','ยืนยันการจอง'],['REGISTRATION_WAITING','รอห้องบัตร'],['REGISTRATION_CALLED','เจ้าหน้าที่เรียก'],['REGISTRATION_IN_PROGRESS','กำลังเปิด Visit'],['SENT_TO_DEPARTMENT','ส่งไปยังแผนกแล้ว']];
const titles={BOOKED:'จองคิวเรียบร้อยแล้ว',REGISTRATION_WAITING:'กำลังรอห้องบัตร',REGISTRATION_CALLED:'เจ้าหน้าที่ห้องบัตรเรียกแล้ว',REGISTRATION_IN_PROGRESS:'กำลังลงทะเบียนและเปิด Visit',SENT_TO_DEPARTMENT:'เปิด Visit และส่งแผนกแล้ว'};
let activeToken='';
let scannerStream=null;
const $=id=>document.getElementById(id);
function tokenFrom(value){const raw=String(value||'').trim();try{const url=new URL(raw);return url.searchParams.get('t')||url.pathname.split('/').filter(Boolean).pop()||raw}catch{return raw}}
function thaiDate(value){if(!value)return '—';const d=new Date(value.includes('T')?value:`${value}T12:00:00+07:00`);return new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}).format(d)}
function currentIndex(step){const aliases={WAITING:'REGISTRATION_WAITING',CALLED:'REGISTRATION_CALLED',CHECKED_IN:'REGISTRATION_WAITING',SERVING:'REGISTRATION_IN_PROGRESS',COMPLETED:'SENT_TO_DEPARTMENT'};return Math.max(0,steps.findIndex(x=>x[0]===(aliases[step]||step)))}
async function loadStatus(token){activeToken=tokenFrom(token);$('lookupError').classList.add('hidden');try{const response=await fetch(`${api}?action=queue-status&token=${encodeURIComponent(activeToken)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่พบข้อมูลคิว');render(body.data);history.replaceState(null,'',`?t=${encodeURIComponent(activeToken)}`)}catch(error){$('lookupCard').classList.remove('hidden');$('statusCard').classList.add('hidden');$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}}
function render(data){$('lookupCard').classList.add('hidden');$('statusCard').classList.remove('hidden');$('queueNo').textContent=data.queue_no||'ยังไม่ออกคิว';$('customer').textContent=data.customer_display;$('location').textContent=`${data.branch_name} · ${data.department_name}`;$('service').textContent=data.service_name||data.department_name;$('reference').textContent=`${data.reference_no} · ช่วงลงทะเบียน ${thaiDate(data.slot_date)} เวลา ${data.start_time}–${data.end_time} น.`;$('statusTitle').textContent=titles[data.current_step]||'กำลังดำเนินการ';$('waitTime').textContent=data.current_step==='SENT_TO_DEPARTMENT'?'ส่งต่อแล้ว':data.estimated_wait_minutes===null?'กำลังประเมิน':data.estimated_wait_minutes<=0?'ใกล้ถึงคิว':`ประมาณ ${data.estimated_wait_minutes} นาที`;$('nextAction').textContent=data.current_step==='BOOKED'?'กรุณาเช็กอินที่ Kiosk เมื่อมาถึง':data.current_step==='SENT_TO_DEPARTMENT'?'กรุณาไปยังแผนกตามที่เจ้าหน้าที่แจ้ง':'โปรดรอเจ้าหน้าที่ห้องบัตรเรียกตามหมายเลขคิว';const index=currentIndex(data.current_step);$('timeline').innerHTML=steps.map((s,i)=>`<li class="step ${i<index?'done':i===index?'current':''}"><div class="step-mark">${i<index?'✓':i+1}</div><div><strong>${s[1]}</strong><span>${i<index?'ดำเนินการแล้ว':i===index?'ขั้นตอนปัจจุบัน':'รอดำเนินการ'}</span></div></li>`).join('')}
$('lookupForm').onsubmit=e=>{e.preventDefault();loadStatus($('tokenInput').value)};$('refreshButton').onclick=()=>loadStatus(activeToken);$('newLookup').onclick=()=>{history.replaceState(null,'',location.pathname);$('statusCard').classList.add('hidden');$('lookupCard').classList.remove('hidden');$('tokenInput').value='';$('tokenInput').focus()};
function stopScanner(){if(scannerStream){scannerStream.getTracks().forEach(track=>track.stop());scannerStream=null}$('scannerVideo').srcObject=null}
function closeScanner(){stopScanner();$('scannerDialog').classList.add('hidden')}
async function openScanner(){$('scannerDialog').classList.remove('hidden');$('scannerError').classList.add('hidden');if(!('BarcodeDetector'in window)){$('scannerError').textContent='เบราว์เซอร์นี้ยังไม่รองรับการอ่าน QR อัตโนมัติ กรุณาใช้ Chrome รุ่นล่าสุดหรือกรอกรหัสแทน';$('scannerError').classList.remove('hidden');return}try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});$('scannerVideo').srcObject=scannerStream;await $('scannerVideo').play();const detector=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!scannerStream)return;const codes=await detector.detect($('scannerVideo')).catch(()=>[]);if(codes[0]){const token=tokenFrom(codes[0].rawValue);closeScanner();$('tokenInput').value=token;loadStatus(token);return}requestAnimationFrame(scan)};scan()}catch(error){stopScanner();$('scannerError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้อง หรือกรอกรหัสติดตามแทน';$('scannerError').classList.remove('hidden')}}
$('scanQrButton').onclick=openScanner;$('startScanner').onclick=openScanner;$('closeScanner').onclick=closeScanner;$('scannerDialog').onclick=event=>{if(event.target===$('scannerDialog'))closeScanner()};document.querySelectorAll('[data-status-tab]').forEach(button=>button.onclick=()=>{const action=button.dataset.statusTab;if(action==='refresh'&&activeToken){loadStatus(activeToken);return}$('statusCard').classList.add('hidden');$('lookupCard').classList.remove('hidden');$('tokenInput').focus()});
function updateClock(){$('clock').textContent=new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Asia/Bangkok'}).format(new Date())+' น.'}updateClock();setInterval(updateClock,30000);const initial=new URLSearchParams(location.search).get('t');if(initial)loadStatus(initial);
